#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> v;
    v.push_back({t});
    v.push_back({b});
    v.push_back({c});

    if (find(v.begin(), v.end(), {t}) != v.end()) {
        cout << "找到了喵" << endl;
    } else {
        cout << "没有喵" << endl;
    }
    return 0;
}
